// S1815b (2026-11-02): B2 laikinos klaidos (503 no tomes available ir pan.) — iki 5 bandymų su nauju upload URL, kaip rekomenduoja B2
$bandymas = 0;
while (true) {
$bandymas++;
$u = b2($api.'/b2api/v3/b2_get_upload_url',
        array('Authorization: '.$tok, 'Content-Type: application/json'),
        array('bucketId' => $CR['bucketId']));
if ($u['http'] !== 200) ps_fail('b2_get_upload_url: HTTP '.$u['http'].' '.($u['json']['code'] ?? ''), $VISI);

$vardas  = rtrim($CR['prefix'],'/').'/'.gmdate('Y/m').'/petshop-'.$stamp.'.tar.gz.enc';
$turinys = file_get_contents($tmpEnc);
$up = b2($u['json']['uploadUrl'],
     array('Authorization: '.$u['json']['authorizationToken'],
           'X-Bz-File-Name: '.rawurlencode($vardas),
           'Content-Type: application/octet-stream',
           'X-Bz-Content-Sha1: '.$sha1,
           'Content-Length: '.$galutinis),
     $turinys, true);
unset($turinys);
if ($up['http'] === 200) break;
if ($bandymas >= 5 || !in_array((int)$up['http'], array(0, 408, 429, 500, 503), true))
    ps_fail('įkėlimas: HTTP '.$up['http'].' '.($up['json']['code'] ?? '').' '.($up['json']['message'] ?? $up['err']), $VISI);
lg('B2 laikina klaida: HTTP '.$up['http'].' '.($up['json']['code'] ?? $up['err']).' — bandymas '.$bandymas.', kartoju');
sleep(5 * $bandymas);
}
